TLM.f("Tempora/Pasc2-0",{"officium":"Dominica II Post Pascha","rule":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 32:5-6"},{"k":"text","la":"Misericórdia Dómini plena est terra, allelúja: verbo Dómini cœli firmáti sunt, allelúja, allelúja."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Misericórdia Dómini plena est terra, allelúja: verbo Dómini cœli firmáti sunt, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui in Fílii tui humilitáte jacéntem mundum erexísti: fidélibus tuis perpétuam concéde lætítiam; ut, quos perpétuæ mortis eripuísti cásibus, gáudiis fácias pérfrui sempitérnis."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Petri 2:21-25"},{"k":"text","la":"Caríssimi: Christus passus est pro nobis, vobis relínquens exémplum, ut sequámini vestígia ejus. Qui peccátum non fecit, nec invéntus est dolus in ore ejus: qui cum maledicerétur, non maledicébat: cum paterétur, non comminabátur: tradébat autem judicánti se injúste: qui peccáta nostra ipse pértulit in córpore suo super lignum: ut, peccátis mórtui, justítiæ vivámus: cujus livóre sanáti estis. Erátis enim sicut oves errántes, sed convérsi estis nunc ad pastórem et epíscopum animárum vestrárum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 24:35"},{"k":"text","la":"Cognovérunt discípuli Dóminum Jesum in fractióne panis. Allelúja"},{"k":"ref","la":"Joannes 10:14"},{"k":"text","la":"Ego sum pastor bonus: et cognósco oves meas, et cognóscunt me meæ. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 10:11-16"},{"k":"text","la":"In illo témpore: Dixit Jesus pharisǽis: Ego sum pastor bonus. Bonus pastor ánimam suam dat pro óvibus suis. Mercenárius autem et qui non est pastor, cujus non sunt oves própriæ, videt lupum veniéntem, et dimíttit oves et fugit: et lupus rapit et dispérgit oves: mercenárius autem fugit, quia mercenárius est et non pértinet ad eum de óvibus. Ego sum pastor bonus: et cognósco meas et cognóscunt me meæ. Sicut novit me Pater, et ego agnósco Patrem, et ánimam meam pono pro óvibus meis. Et álias oves hábeo, quæ non sunt ex hoc ovíli: et illas opórtet me addúcere, et vocem meam áudient, et fiet unum ovíle et unus pastor."}],"Offertorium":[{"k":"ref","la":"Ps 62:2; 62:5"},{"k":"text","la":"Deus, Deus meus, ad te de luce vígilo: et in nómine tuo levábo manus meas, allelúja."}],"Secreta":[{"k":"text","la":"Benedictiónem nobis, Dómine, cónferat salutárem sacra semper oblátio: ut, quod agit mystério, virtúte perfíciat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 10:14"},{"k":"text","la":"Ego sum pastor bonus, allelúja: et cognósco oves meas, et cognóscunt me meæ, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut, vivificatiónis tuæ grátiam consequéntes, in tuo semper múnere gloriémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6ec5ef5b01f9ccc7":{"t":"Ps 32, 5-6, Ps 32, 1\n(Ps 32, 5-6) Milosrđa je Gospodnjega puna zemlja, <i>aleluja</i>!\nRiječju su Gospodnjom utvrđena nebesa, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 32, 1). Radujte se, pravednici, u Gospodinu, dobrima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 32, 5-6) Milosrđa je Gospodnjega puna zemlja, <i>aleluja</i>!\nRiječju su Gospodnjom utvrđena nebesa, <i>aleluja</i>, <i>aleluja</i>."},"9b054e1ad1cc6d88":{"t":"<i>Pomolimo se</i>.\nBože, koji si poniženjem svoga Sina podigao oboreno čovječanstvo, daj svojim vjernicima da se uvijek raduju tako, da onima koje si izbavio od vječne propasti dadeš uživati vječno veselje.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"4e98e768a529d23e":{"t":"1 Pt 2, 21-25\nČitanje Poslanice bl. Petra apostola. Predragi: Krist je trpio za nas i ostavio vam primjer, da idete njegovim stopama. On ne učini grijeha i u njegovim se ustima ne nađe prijevare. Kad su ga grdili, nije uzvraćao grdnjom, kad je trpio, nije prijetio, nego se prepustio onome koji jedini sudi pravedno. On je na svom vlastitom tijelu ponio naše grijehe na križ, da mi umrvši grijehu živimo za pravdu. Izliječili ste se njegovim ranama. Bili ste kao zalutale ovce, ali ste se sada obratili k pastiru i čuvaru vaših duša."},"6c602ad1560ff6bf":{"t":"Lk 24, 35, Iv 10, 14\n<i>Aleluja</i>, <i>aleluja</i>.\n(Lk 24, 35) Učenici su prepoznali Gospodina Isusa po lomljenju kruha, <i>aleluja</i>.\n(Iv 10, 14) Ja sam dobri pastir i poznajem svoje ovce, a moje ovce poznaju mene, <i>aleluja</i>."},"24aa582fd8f56d69":{"t":"Iv 10, 11-16\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus farizejima: Ja sam dobri pastir. Dobar pastir daje svoj život za svoje ovce, a najamnik, koji nije pastir i nije vlasnik ovaca, kad vidi da dolazi vuk, ostavi ovce i bježi, pa vuk grabi i razgoni ovce. Najamnik bježi, jer je najamnik i nije mu stalo do ovaca. Ja sam dobri pastir i poznajem svoje ovce, a moje ovce poznaju mene, kao što Otac poznaje mene i kao što ja poznajem Oca. I ja dajem svoj život za svojeg ovce. Imam i drugih ovaca, koje nisu iz ovog ovčinjaka. I njih mi treba dovesti i čut će moj glas i bit će jedno stado i jedan pastir."},"4119f0bfe80dd6b4":{"t":"Ps 62, 2 i 5\nBože, Bože moj, pred tobom bdijem od svanuća, i u tvoje ću ime dizati svoje ruke, <i>aleluja</i>."},"1a11a54401cf57f1":{"t":"Sveti prinos, Gospodine, neka nam uvijek donese spasonosni blagoslov, da svojom snagom dovrši ono što otajstveno predstavlja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"ca3dcc6d74e17a81":{"t":"Iv 10, 14\nJa sam dobri pastir <i>aleluja</i>,\ni poznam svoje ovce, a moje ovce poznaju mene, <i>aleluja</i>, <i>aleluja</i>."},"196c09cf5177e8ff":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, svemogući Bože, da se uvijek dičimo tvojim darom mi koji smo primili tvoju milost novog života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
